def find_min_n(m):
    def count_ways(n, k):
        if n == 0:
            return 1
        if k == 1:
            return 0
        count = 0
        i = 1
        while i <= n:
            count += count_ways(n - i, k - 1)
            i *= k
        return count

    left, right = 1, 10**18
