    while left <= right:
        mid = (left + right) // 2
        total_ways = 0
        for k in range(2, mid + 1):
            total_ways += count_ways(mid, k)
            if total_ways > m:
                break
        if total_ways == m:
            result = mid
            right = mid - 1
        elif total_ways < m:
            left = mid + 1
        else:
            right = mid - 1
    return result

